const api=new Client();let d,busy=false,toastTimer;
const photoCache=new Map(),loadingPhotos=new Set();let photoEpoch=api.sessionEpoch;
function clearPhotos(){for(const url of photoCache.values())URL.revokeObjectURL(url);photoCache.clear();loadingPhotos.clear();photoEpoch=api.sessionEpoch;}
async function hydratePhotos(){if(!api.external)return;if(photoEpoch!==api.sessionEpoch)clearPhotos();for(const img of document.querySelectorAll('img[data-photo-id]')){const id=img.dataset.photoId;if(photoCache.has(id)){img.src=photoCache.get(id);continue;}if(loadingPhotos.has(id))continue;loadingPhotos.add(id);const epoch=api.sessionEpoch;try{const response=await api.resource('photo/'+encodeURIComponent(id));if(!response.ok||!response.headers.get('content-type')?.startsWith('image/jpeg'))continue;const blob=await response.blob();if(epoch!==api.sessionEpoch)continue;const url=URL.createObjectURL(blob);photoCache.set(id,url);for(const other of document.querySelectorAll('img[data-photo-id]'))if(other.dataset.photoId===id)other.src=url;}catch{}finally{loadingPhotos.delete(id);}}}
new MutationObserver(()=>{void hydratePhotos();}).observe(document.documentElement,{childList:true,subtree:true});
