const labname=id=>!id?t('中心待購庫存','Center stock'):state.lang==='en'?({center:'CNMM','lab-a':'Lab A','lab-b':'Lab B'}[id]||d.labs.find(x=>x.id===id)?.name):d.labs.find(x=>x.id===id)?.name||id;
const fmt=value=>value?new Intl.DateTimeFormat(state.lang==='en'?'en-GB':'zh-TW',{timeZone:'Asia/Taipei',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(value)):'—';
const time=value=>new Date(+new Date(value)+8*HOUR).toISOString().slice(11,16);
const range=b=>`${fmt(b.start)} – ${dateKey(+new Date(b.start))===dateKey(+new Date(b.end))?time(b.end):fmt(b.end)}`;
