function probeCard(p){const published=d.probe_tables.find(s=>s.id===p.table_id)?.status==='published',eligible=canSign(d,me(),p),manage=management()&&labAccess(me(),p.lab_id);return `<article class="probe-cell ${p.status}"><div class="cell-top"><span class="slot">${esc(p.slot)}</span>${badge(p.status,!published?t('草稿・不可領用','Draft · unavailable'):!p.lab_id?t('待購庫存','For purchase'):null)}</div><strong class="serial">${esc(p.serial)}</strong><div class="owner">${esc(labname(p.lab_id))}<br>${esc(p.model)}</div><div class="holder">${p.holder?`${t('拿取人','Holder')}: ${esc(username(p.holder))}`:money(p.price)} · ${label(p.condition)}</div><div class="card-actions">${!p.lab_id&&p.status==='available'?button(manager(me())?t('直接購買','Purchase'):t('申請購買','Request purchase'),'purchase',p.id,'small',active(me())&&published?'':'disabled'):p.status==='available'?button(t('簽署耗材','Sign out'),'sign',p.id,'small',(eligible||manage)&&active(me())&&published?'':'disabled'):''}${p.holder&&(p.holder===me().id||manage)?button(t('更新狀況','Condition'),'condition',p.id)+button(t('歸還','Return'),'return',p.id):''}${manage?button(t('領用權限','Access'),'permissions',p.id)+(p.status==='in_use'?button(t('更正位置','Correct position'),'correct-probe',p.id):button(t('盤點／調撥','Adjust inventory'),'stock-adjust',p.id)):''}${!published?`<small>${t('針盒尚未發佈，不能購買或簽領。','Publish this box before purchasing or signing out items.')}</small>`:''}${published&&!eligible&&p.status==='available'&&p.lab_id?`<small>${t('尚未取得這支耗材的領用權限；請聯絡實驗室管理者。','Access has not been granted. Contact your lab manager.')}</small>`:''}${manage&&p.status==='inspection'?button(t('檢查處理','Inspect'),'review',p.id):''}</div></article>`;}
function calendarView(){
 const i=instrument(),start=state.week,days=Array.from({length:7},(_,n)=>plusDays(start,n)),hours=state.calendarHours==='all'?Array.from({length:24},(_,h)=>h):Array.from({length:13},(_,h)=>h+9);
 const selection=`<div class="selection-bar"><div><strong id="selection-count"></strong><div id="selection-detail"></div><small id="selection-age"></small><small id="selection-error" role="status"></small></div><div class="toolbar-group">${button(t('重新檢查選取','Recheck selection'),'plan-recheck')}${button(t('清除','Clear'),'clear-selection')}${button(t('新增預約','New booking'),'book-selection','','','id="book-selection"')}</div></div>`;
 return head(t('儀器預約','Instrument bookings'),'')+instrumentBar()+qualificationBanner()+(d.bookings.some(b=>resourceId(b)===i.id&&b.status==='checked_in'&&Date.parse(b.end)<Date.now())?`<p class="note overdue-notice">${t('前一場尚未簽退；下一位簽到前，需先確認儀器已釋放。','The previous session is still open. Release the instrument before the next check-in.')}</p>`:'')+`<div class="toolbar"><div class="toolbar-group">${button('←','prev-week','','secondary small',`aria-label="${t('上一週','Previous week')}"`)}${button(t('今天','Today'),'this-week')}${button('→','next-week','','secondary small',`aria-label="${t('下一週','Next week')}"`)}<input type="date" id="calendar-date" aria-label="${t('跳至日期','Go to date')}" value="${state.week}">${button(t('下一個可預約日','Next available day'),'next-available')}</div><label>${t('顯示時段','Hours')} <select id="calendar-hours">${options([['day','09:00–22:00'],['all',t('全天 24 小時','All 24 hours')]],state.calendarHours)}</select></label></div><div class="calendar-legend">${badge('selected',t('已選取','Selected'))}${badge('pending')}${badge('booked')}${badge('checked_in')}${badge('buffer_conflict',t('準備／清潔','Setup / cleanup'))}<span>${t('點選多格；拖曳或 Shift 可連續選取','Select multiple slots; drag or Shift for a range')}</span></div>${selection}<div class="calendar-wrap"><div class="week-calendar"><div class="cal-head">UTC+8</div>${days.map(day=>`<div class="cal-head ${day===dateKey()?'today':''}">${new Intl.DateTimeFormat(state.lang==='en'?'en':'zh-TW',{weekday:'short',timeZone:'Asia/Taipei'}).format(new Date(day+'T12:00:00+08:00'))}<strong>${day.slice(5)}</strong></div>`).join('')}${hours.map(h=>`<div class="cal-time">${String(h).padStart(2,'0')}:00</div>${days.map(day=>{
 const ts=+new Date(`${day}T${String(h).padStart(2,'0')}:00:00+08:00`),here=d.bookings.filter(b=>resourceId(b)===i.id&&['pending','booked','checked_in','completed'].includes(b.status)&&ts>=+new Date(b.start)&&ts<+new Date(b.end)),b=here.find(occupied)||here.find(b=>b.user_id===me().id)||here[0],detail=b&&(occupied(b)||b.user_id===me().id||b.status==='completed');let blocked='',code='';
 if(!detail)try{validateSlot(d,me(),new Date(ts).toISOString(),new Date(ts+HOUR).toISOString(),Date.now(),undefined,false,i.id);}catch(e){blocked=err(e);code=e.message;}
 const blockedLabel=code==='buffer_conflict'?t('準備／清潔','Setup / cleanup'):code==='maintenance_window'?t('維修','Maintenance'):code==='waitlist_hold'?t('候補保留','Waitlist hold'):code==='invalid_time'?t('已過期','Past'):['weekend_restricted','evening_restricted','instrument_access'].includes(code)?t('資格限制','Restricted'):code==='instrument_unavailable'?t('暫停','Paused'):t('未開放','Unavailable');
 return `<button class="cal-slot ${b?b.status:''} ${blocked?'blocked '+code:''} ${b?.user_id===me().id?'mine':''} ${state.selected.has(ts)?'selected':''}" data-action="${detail?'booking':blocked?'unavailable-slot':'select-slot'}" data-id="${b?.id||''}" data-ts="${ts}" ${!detail&&!blocked?`aria-pressed="${state.selected.has(ts)}"`:''} ${blocked?`data-reason="${esc(blocked)}" title="${esc(blocked)}"`:''} aria-label="${day} ${String(h).padStart(2,'0')}:00 ${b?label(b.status):blocked?blockedLabel:t('可選取','Available')}">${b?`<strong>${label(b.status)}</strong><small>${b.private?'':esc(username(b.user_id))}</small>`:blocked?`<span class="blocked-label">${blockedLabel}</span>`:`<span class="slot-plus">＋</span>`}</button>`;
 }).join('')}`).join('')}</div></div>`;
}

function updateSelection(){
 if(!$('#selection-count'))return;
 document.querySelectorAll('[data-action="select-slot"]').forEach(el=>{const selected=state.selected.has(Number(el.dataset.ts));el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',String(selected));});
 if(!state.selected.size)state.selectionStarted=null;else state.selectionStarted||=Date.now();
 $('#selection-age').textContent=state.selected.size?t('選取於 '+fmt(state.selectionStarted)+'；尚未保留時段','Selected '+fmt(state.selectionStarted)+'; times are not held'):'';
 $('#selection-count').textContent=state.selected.size?t(`已選取 ${state.selected.size} 小時`,`${state.selected.size} hours selected`):t('尚未選取時段','No slots selected');
 $('#selection-detail').textContent=selectionGroups([...state.selected]).map(range).join(' / ');let message='';try{validateSelection(d,me(),[...state.selected],Date.now(),state.instrument);}catch(e){if(state.selected.size)message=err(e);}
 $('#selection-error').textContent=message;$('#book-selection').disabled=!state.selected.size||!!message;
}
function selectSlot(ts,shift){
 const values=shift&&state.anchor?rangeSelection(state.anchor,ts):[ts];
 for(const value of values){const el=document.querySelector(`[data-action="select-slot"][data-ts="${value}"]`);if(!el||el.disabled)continue;if(!shift&&state.selected.has(value))state.selected.delete(value);else state.selected.add(value);}
 state.anchor=ts;updateSelection();
}
function bindSelection(){
 updateSelection();const grid=$('.week-calendar');if(!grid)return;
 grid.onpointerdown=e=>{const el=e.target.closest('[data-action="select-slot"]');if(e.pointerType==='touch'||e.button!==0||!el||el.disabled)return;state.suppressClick=false;state.drag={start:Number(el.dataset.ts),base:new Set(state.selected),remove:state.selected.has(Number(el.dataset.ts)),moved:false};};
 grid.onpointerover=e=>{const el=e.target.closest('[data-action="select-slot"]');if(!state.drag||!el||el.disabled)return;try{const values=rangeSelection(state.drag.start,Number(el.dataset.ts));if(values.length>1)state.drag.moved=true;state.selected=new Set(state.drag.base);for(const value of values){const cell=grid.querySelector(`[data-action="select-slot"][data-ts="${value}"]`);if(cell&&!cell.disabled){if(state.drag.remove)state.selected.delete(value);else state.selected.add(value);}}updateSelection();}catch{}};
}
document.addEventListener('pointerup',()=>{if(state.drag?.moved){state.suppressClick=true;setTimeout(()=>{state.suppressClick=false;},0);}state.drag=null;});
document.addEventListener('pointercancel',()=>{state.drag=null;});
function instrumentBar(){const i=instrument();return `<section class="instrument-context"><div class="instrument-picker"><label for="instrument-select">${t('儀器','Instrument')}</label><select id="instrument-select">${options(d.instruments.map(i=>[i.id,i.name]),i.id)}</select>${badge(i.status,i.status==='available'?t('開放預約','Available'):label(i.status))}${i.location?`<small>${esc(i.location)}</small>`:''}${management()&&system(me())?button(t('＋ 新增儀器','＋ Add instrument'),'new-instrument'):''}</div><nav class="resource-tabs" aria-label="${t('儀器功能','Instrument sections')}">${[['calendar',t('預約時段','Reservations')],['probes',t('耗材','Consumables')],...(management()&&instrumentAdmin(me(),i)?[['instrument-settings',t('儀器設定','Instrument settings')]]:[])].map(([id,name])=>`<button data-resource-page="${id}" class="${state.page===id?'active':''}">${name}</button>`).join('')}</nav></section>`;}
function probesView(){return wf.sheetView();}
function checkoutDialog(id){const b=d.bookings.find(b=>b.id===id),i=instrumentFor(d,resourceId(b));modal(t('預約簽退','Check out'),`<p>${esc(b.instrument_name||i.name)} · ${range(b)}</p>${field(t('儀器使用狀態','Instrument condition'),`<select name="instrument_status" required><option value="">${t('請選擇','Select')}</option>${options(i.checkout_statuses.map(o=>[o.id,optionName(o)]),'')}</select>`)}${field(t('使用模式','Usage mode'),`<select name="usage_mode" required><option value="">${t('請選擇','Select')}</option>${options(i.modes.map(o=>[o.id,optionName(o)]),'')}</select>`)}${field(t('使用紀錄／異常說明','Usage / issue notes'),'<textarea name="notes" maxlength="5000"></textarea>')}<p id="checkout-hint" class="note"></p>`,f=>run('checkout_booking',{id,instrument_status:f.get('instrument_status'),usage_mode:f.get('usage_mode'),notes:f.get('notes')}));const select=$('#dialog [name=instrument_status]');select.onchange=()=>{const o=i.checkout_statuses.find(o=>o.id===select.value);$('#dialog [name=notes]').required=!!o?.requires_notes;$('#checkout-hint').textContent=o?.blocks_booking?t('此狀態會暫停新的預約，待管理者恢復開放。','This condition pauses new reservations until a manager reopens the instrument.'):o?.requires_notes?t('請填寫異常說明。','Please describe the issue.'):'';};}
function optionEditor(kind,items){return `<div class="option-editor" data-kind="${kind}">${items.map(o=>optionRow(kind,o)).join('')}</div>${button(t('＋ 新增選項','＋ Add option'),'add-option',kind,'secondary small','type="button"')}`;}
function optionRow(kind,o={}){return `<div class="option-row" data-option-kind="${kind}" data-option-id="${esc(o.id||'')}"><div class="option-text"><input name="${kind}_name" value="${esc(o.name||'')}" placeholder="${t('選項名稱','Option name')}" aria-label="${t('選項名稱','Option name')}" maxlength="100" required><input name="${kind}_en" value="${esc(o.en||'')}" placeholder="English" aria-label="English label" maxlength="100"></div>${kind==='checkout_statuses'?`<label><input type="checkbox" data-option-flag="requires_notes" ${o.requires_notes?'checked':''}>${t('必填說明','Require notes')}</label><label><input type="checkbox" data-option-flag="blocks_booking" ${o.blocks_booking?'checked':''}>${t('暫停預約','Pause booking')}</label>`:''}${button('×','remove-option','','icon-btn',`type="button" aria-label="${t('移除選項','Remove option')}"`)}</div>`;}
function instrumentSettingsView(){const i=instrument(),r=rulesFor(d,me(),i.id);if(!management()||!instrumentAdmin(me(),i))return empty();return head(t('儀器設定','Instrument settings'),'')+instrumentBar()+`<div class="settings-grid">${panel(t('儀器資料','Instrument details'),`<div class="rule-values"><div>${t('名稱','Name')}<b>${esc(i.name)}</b></div><div>${t('位置','Location')}<b>${esc(i.location||'—')}</b></div><div>${t('狀態','Status')}<b>${i.status==='available'?t('開放預約','Available'):label(i.status)}</b></div><div>${t('預約資格','Booking access')}<b>${t('依個人儀器認證','Individual instrument certification')}</b></div><div>${t('一般開放時段','Standard hours')}<b>${r.start_hour}:00–${r.end_hour}:00</b></div></div>${button(t('編輯儀器','Edit instrument'),'edit-instrument',i.id,'')}`)}${panel(t('簽退選單','Check-out options'),`<h3>${t('使用模式','Usage modes')}</h3><div class="option-summary">${i.modes.map(o=>badge('available',optionName(o))).join('')}</div><h3>${t('儀器狀態','Instrument conditions')}</h3><div class="option-summary">${i.checkout_statuses.map(o=>badge(o.blocks_booking?'inspection':'available',optionName(o))).join('')}</div>${button(t('編輯選單','Edit options'),'edit-instrument',i.id)}`)}</div>`;}
function instrumentDialog(id){const current=d.instruments.find(i=>i.id===id),i=current||{...defaultInstrument(),name:'',location:''},r=i.rules||d.rules.global;modal(current?t('編輯儀器','Edit instrument'):t('新增儀器','Add instrument'),`${field(t('儀器名稱','Instrument name'),`<input name="name" value="${esc(i.name)}" maxlength="100" required>`)}${field(t('位置','Location'),`<input name="location" value="${esc(i.location)}" maxlength="200">`)}<div class="form-grid">${field(t('儀器狀態','Instrument status'),`<select name="status">${options(['available','maintenance','inactive'].map(x=>[x,x==='available'?t('開放預約','Available'):label(x)]),i.status)}</select>`)}</div>${system(me())?`<details><summary>${t('儀器管理員','Instrument managers')}</summary><h3>${t('儀器管理員','Instrument managers')}</h3>${d.users.filter(manager).map(u=>`<label class="check-row"><input type="checkbox" name="manager_ids" value="${esc(u.id)}" ${i.manager_ids.includes(u.id)?'checked':''}>${esc(username(u.id))}</label>`).join('')}</details>`:''}<details><summary>${t('預約規則','Booking rules')}</summary><label class="check-row"><input type="checkbox" name="custom_rules" ${i.rules?'checked':''}>${t('使用此儀器的個別規則','Use instrument-specific rules')}</label><div class="form-grid">${field(t('開始時刻','Start hour'),`<input name="start_hour" type="number" min="0" max="23" value="${r.start_hour}" required>`)}${field(t('結束時刻','End hour'),`<input name="end_hour" type="number" min="1" max="24" value="${r.end_hour}" required>`)}</div>${field(t('單次上限（小時）','Session limit (hours)'),`<input name="max_hours" type="number" min="1" max="24" value="${r.max_hours}" required>`)}<div class="form-grid">${['weekend','evening'].map(k=>field(k==='weekend'?t('週末','Weekends'):t('晚間','After hours'),`<select name="${k}">${options(['all','advanced','closed'].map(x=>[x,label(x)]),r[k])}</select>`)).join('')}</div>${field(t('延長審核者','Extension approver'),`<select name="extension_role">${options(['lab_manager','system_admin'].map(x=>[x,label(x)]),r.extension_role)}</select>`)}${field(t('每小時費率（NT$）','Hourly rate (NT$)'),`<input name="hourly_rate" type="number" min="0" step="0.01" value="${r.hourly_rate??''}">`)}</details><h3>${t('使用模式','Usage modes')}</h3>${optionEditor('modes',i.modes)}<h3>${t('簽退時的儀器狀態','Instrument conditions at check-out')}</h3>${optionEditor('checkout_statuses',i.checkout_statuses)}`,async f=>{const readOptions=kind=>[...$('#dialog').querySelectorAll(`[data-option-kind="${kind}"]`)].map(row=>({id:row.dataset.optionId,name:row.querySelector(`[name="${kind}_name"]`).value,en:row.querySelector(`[name="${kind}_en"]`).value,requires_notes:!!row.querySelector('[data-option-flag="requires_notes"]')?.checked,blocks_booking:!!row.querySelector('[data-option-flag="blocks_booking"]')?.checked}));const rules=f.has('custom_rules')?{start_hour:Number(f.get('start_hour')),end_hour:Number(f.get('end_hour')),max_hours:Number(f.get('max_hours')),weekend:f.get('weekend'),evening:f.get('evening'),extension_role:f.get('extension_role'),hourly_rate:f.get('hourly_rate')===''?null:Number(f.get('hourly_rate'))}:null;const result=await run('save_instrument',{id:current?.id,name:f.get('name'),location:f.get('location'),status:f.get('status'),access:f.get('access')||i.access,manager_ids:f.getAll('manager_ids'),authorized_user_ids:i.authorized_user_ids,rules,modes:readOptions('modes'),checkout_statuses:readOptions('checkout_statuses')});state.instrument=result.id;state.calendarReady=false;state.selected.clear();state.page='instrument-settings';});$('#dialog').classList.add('wide-dialog');}

function pendingCount(){return pendingRequests().length+(d.attendance_requests||[]).filter(x=>x.status==='pending'&&x.user_id!==me().id&&x.requested_by!==me().id).length;}
function pendingRequests(){return [...d.bookings.filter(b=>b.status==='pending').map(b=>({...b,kind:'booking'})),...d.purchases.filter(x=>x.status==='pending').map(x=>({...x,kind:'purchase'})),...d.extensions.filter(x=>x.status==='pending').map(x=>({...x,kind:'extension'}))].filter(x=>system(me())||x.lab_id===me().lab_id);}
function requestTitle(x,kind){if(kind==='booking')return `${iname(x.instrument_id)} · ${range(x)}${x.booking_method?' · '+methodLabel(x.booking_method):''}`;if(kind==='purchase')return `${d.probes.find(p=>p.id===x.probe_id)?.serial||x.probe_id} · ${money(x.price)}`;return `${bookingReviewLabel(d,x.booking_id,fmt,t)} · ${t('延長至','Extend to')} ${fmt(x.end)}`;}
function requestTable(items,kind){return items.length?`<section class="panel table-scroll"><table class="table"><thead><tr><th>${t('申請者','Applicant')}</th><th>${t('內容','Request')}</th><th>${t('狀態','Status')}</th><th>${t('處理說明','Review')}</th></tr></thead><tbody>${items.map(x=>`<tr><td>${esc(username(x.user_id))}</td><td>${esc(requestTitle(x,kind))}</td><td>${badge(x.status)}</td><td>${esc(x.reason||(x.approved_by?username(x.approved_by):'—'))}</td></tr>`).join('')}</tbody></table></section>`:empty();}
function approvalsViewBase(){const requests=pendingRequests();return head(t('申請審核','Approvals'),system(me())?t('跨實驗室審核與責任紀錄。','Review requests across all labs.'):t('你核准的成員行為，由你負責。僅顯示直屬實驗室申請。','You are responsible for approved member activity. Only your lab’s requests appear.'))+(requests.length?`<div class="approval-grid">${requests.map(x=>{const role=x.kind==='extension'?rulesFor(d,d.users.find(u=>u.id===x.user_id),resourceId(x)).extension_role:'lab_manager',allowed=system(me())||role!=='system_admin';return panel(esc(requestTitle(x,x.kind)),`<p>${esc(username(x.user_id))} · ${esc(labname(x.lab_id))}</p>${x.purpose?`<p class="wrap">${esc(x.purpose)}</p>`:''}<p class="note">${t('核准權限','Approval authority')}: ${label(role)}</p><div class="card-actions">${button(t('核准','Approve'),`approve-${x.kind}`,x.id,'',allowed?'':'disabled')}${button(t('不核准','Decline'),`reject-${x.kind}`,x.id,'danger',allowed?'':'disabled')}</div>`,t({booking:'儀器預約',purchase:'耗材購買',extension:'延長預約'}[x.kind],{booking:'Booking',purchase:'Consumable purchase',extension:'Extension'}[x.kind]));}).join('')}</div>`:pendingCount()?'':panel(t('已處理完畢','All caught up'),empty(t('目前沒有待審申請。','There are no pending requests.'))));}
function approvalsView(){return approvalsViewBase()+wf.attendancePanel();}
function certLabel(level){return ({none:t('未認證','Not certified'),assisted:t('代工','Assisted only'),basic:t('一般','Standard'),advanced:t('進階','Advanced')})[level]||'—';}
function methodLabel(method){return method==='assisted'?t('代工預約','Assisted booking'):method==='self'?t('自行操作','Self-operated'):'—';}
function qualificationBanner(){const level=qualification(d,me().id,state.instrument);return `<div class="qualification-banner ${level==='none'?'uncertified':''}"><div>${badge(level,certLabel(level))}<span>${level==='none'?t('尚未取得此儀器資格，請聯絡直屬實驗室管理者。','You are not certified for this instrument. Contact your lab manager.'):level==='assisted'?t('僅可預約代工服務','Assisted service bookings only'):level==='basic'?t('自行操作 · 一般開放時段','Self-operated · standard hours'):t('自行操作 · 可依規則使用進階時段','Self-operated · advanced hours as permitted')}</span></div>${management()?button(t('管理認證','Manage certification'),'member-certifications',me().id):''}</div>`;}
function certificationsView(){return head(t('儀器認證','Instrument certification'),system(me())?t('逐人設定各儀器資格','Set each member’s instrument qualification'):t('僅可設定直屬一般成員','Manage your lab’s members'))+`<div class="cert-legend"><span><b>${certLabel('none')}</b> ${t('不可預約','No booking')}</span><span><b>${certLabel('assisted')}</b> ${t('僅代工','Assisted only')}</span><span><b>${certLabel('basic')}</b> ${t('一般時段自操','Standard-hours self-use')}</span><span><b>${certLabel('advanced')}</b> ${t('含規則允許的進階時段','Includes permitted advanced hours')}</span></div><div class="cert-toolbar"><div class="toolbar-group"><input id="cert-search" type="search" aria-label="${t('搜尋成員','Search members')}" placeholder="${t('搜尋姓名或信箱','Search name or email')}" value="${esc(state.certSearch)}">${system(me())?`<select id="cert-lab" aria-label="${t('篩選實驗室','Filter lab')}">${options([['',t('所有實驗室','All labs')],...d.labs.map(l=>[l.id,labname(l.id)])],state.certLab)}</select>`:''}</div><div class="toolbar-group"><span id="cert-change-count" role="status"></span>${button(t('捨棄變更','Discard'),'discard-certifications','','secondary small','id="discard-certifications"')}${button(t('儲存認證','Save certification'),'save-certifications','','','id="save-certifications"')}</div></div><section class="panel table-scroll cert-table"><table class="table"><thead><tr><th>${t('成員 / 單位','Member / lab')}</th>${d.instruments.map(i=>`<th>${esc(i.name)}${i.status!=='available'?`<small>${label(i.status)}</small>`:''}</th>`).join('')}</tr></thead><tbody>${d.users.map(u=>`<tr data-cert-member="${esc(u.id)}"><th scope="row"><strong>${esc(username(u.id))}</strong><small>${esc(labname(u.lab_id))} · ${label(u.role)}</small>${!active(u)?badge('disabled',label(u.status)):''}</th>${d.instruments.map(i=>{const c=certificationFor(d,u.id,i.id),key=JSON.stringify([u.id,i.id]),value=state.certDraft.get(key)?.level||c?.level||'none',editable=manages(me(),u);return `<td><select data-cert-user="${esc(u.id)}" data-cert-instrument="${esc(i.id)}" aria-label="${esc(username(u.id)+' · '+i.name)}" class="cert-select ${value} ${state.certDraft.has(key)?'changed':''}" ${editable?'':'disabled'}>${options(certificationLevels.map(v=>[v,certLabel(v)]),value)}</select><small title="${esc(c?username(c.certified_by)+' · '+fmt(c.certified_at):'')}">${c?t('更新','Updated')+' '+fmt(c.certified_at):t('尚無認證紀錄','No certification record')}</small></td>`;}).join('')}</tr>`).join('')}</tbody></table><div id="cert-empty" class="empty-state" hidden>${t('找不到符合的成員','No matching members')}</div></section>`;}
function bindCertifications(){
 if(!$('#cert-search'))return;
 const filter=()=>{let count=0;document.querySelectorAll('[data-cert-member]').forEach(row=>{const u=d.users.find(u=>u.id===row.dataset.certMember);row.hidden=!!(state.certLab&&u.lab_id!==state.certLab)||!((u.name+' '+(u.email||'')+' '+username(u.id)).toLowerCase().includes(state.certSearch.toLowerCase()));if(!row.hidden)count++;});$('#cert-empty').hidden=!!count;};
 $('#cert-search').oninput=e=>{state.certSearch=e.target.value;filter();};if($('#cert-lab'))$('#cert-lab').onchange=e=>{state.certLab=e.target.value;filter();};
 document.querySelectorAll('[data-cert-user]').forEach(select=>select.onchange=()=>{const user_id=select.dataset.certUser,instrument_id=select.dataset.certInstrument,c=certificationFor(d,user_id,instrument_id),key=JSON.stringify([user_id,instrument_id]);if(select.value===(c?.level||'none'))state.certDraft.delete(key);else state.certDraft.set(key,{user_id,instrument_id,level:select.value,revision:c?.revision||0});select.className='cert-select '+select.value+(state.certDraft.has(key)?' changed':'');updateCertificationCount();});filter();updateCertificationCount();
}
function updateCertificationCount(){const count=state.certDraft.size;$('#cert-change-count').textContent=count?t(count+' 項未儲存',count+' unsaved changes'):t('已儲存','Saved');$('#save-certifications').disabled=!count;$('#discard-certifications').disabled=!count;}

function analyticsView(){return analysisView(state.analyticsResult,state.analysis,{t,instruments:d.instruments,labs:d.labs,admin:system(me()),labName:labname,loading:state.analyticsLoading,error:state.analyticsError});}
async function loadAnalytics(){
 if(!management())return;
 const seq=++state.analyticsSequence;state.analysis.today=dateKey();if(!system(me()))state.analysis.lab=me().lab_id;
 state.analyticsLoading=true;state.analyticsError='';render();
 try{const {from,to,instrument,lab}=state.analysis;const result=await api.request('analytics?'+new URLSearchParams({from,to,instrument,lab}));if(seq===state.analyticsSequence)state.analyticsResult=result;}
 catch(e){if(seq===state.analyticsSequence)state.analyticsError=err(e);}
 finally{if(seq===state.analyticsSequence){state.analyticsLoading=false;if(d&&state.page==='analytics')render();}}
}
function bindAnalytics(){
 if(!$('#analytics-period'))return;
 const filters=state.analysis;
 $('#analytics-period').onchange=e=>{filters.period=e.target.value;if(filters.period!=='custom'){filters.to=dateKey();filters.from=plusDays(filters.to,1-Number(filters.period));loadAnalytics();}};
 for(const key of ['from','to','instrument','lab']){const el=$('#analytics-'+key);if(el)el.onchange=()=>{filters[key]=el.value;if(['from','to'].includes(key))filters.period='custom';loadAnalytics();};}
 if($('#analytics-group'))$('#analytics-group').onchange=e=>{filters.group=e.target.value;render();};
 document.querySelectorAll('[data-analysis-tab]').forEach(el=>el.onclick=()=>{filters.tab=el.dataset.analysisTab;render();});
}

