function table(headers,rows){return rows.length?`<section class="panel table-scroll"><table class="table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></section>`:empty();}
