 const scope=x=>management()||x.user_id===me().id||x.operator_id===me().id,tabs=[['bookings',t('預約與出勤','Bookings & attendance')],['probes',t('耗材使用','Consumable usage')],['requests',t('購買與延長','Purchases & extensions')],['audit',t('操作紀錄','Activity log')]];let content='';
 if(state.tab==='bookings')content=table([t('使用者 / 時段','Member / session'),t('狀態 / 日曆','Status / calendar'),t('實際簽到','Actual check-in'),t('實際簽退','Actual check-out'),t('紀錄 / 負責人','Notes / responsible manager')],d.bookings.filter(b=>!b.private&&scope(b)).map(b=>`<tr><td>${esc(username(b.user_id))}<small>${esc(b.instrument_name||iname(b.instrument_id))} · ${range(b)}</small>${b.booking_method?`<small>${methodLabel(b.booking_method)} · ${certLabel(b.qualification_at_booking)}</small>`:''}</td><td>${badge(b.status)}<small>${calendarLabel(b.calendar_status||'awaiting_approval')}</small></td><td>${fmt(b.checked_in_at)}</td><td>${fmt(b.checked_out_at)}</td><td class="wrap">${esc(optionName(b.instrument_status))} · ${esc(optionName(b.usage_mode))}<small>${esc(b.notes||b.reason||'')}</small><small>${esc(b.responsible_id?username(b.responsible_id):'—')}</small>${(b.user_id===me().id||b.operator_id===me().id)&&['booked','checked_in','completed','no_show','released'].includes(b.status)&&Date.now()>+new Date(b.start)?button(t('出勤補登','Correct attendance'),'attendance-request',b.id):''}</td></tr>`));
 if(state.tab==='probes')content=table([t('耗材','Probe'),t('拿取人 / 登記者','Holder / operator'),t('領用 / 歸還','Taken / returned'),t('狀況 / 備註','Condition / notes')],d.usages.filter(scope).map(x=>`<tr><td>${esc(d.probes.find(p=>p.id===x.probe_id)?.serial||x.probe_id)}</td><td>${esc(username(x.user_id))}<small>${esc(username(x.actor_id))}</small></td><td>${fmt(x.taken_at)}<small>${fmt(x.returned_at)}</small></td><td>${x.condition?label(x.condition):'—'}<small class="wrap">${esc(x.notes)}</small></td></tr>`));
